INSERT INTO `email_outbox` VALUES (52,'reset-27b17d7f600b1d5da2f3725e5bd21305002d77c8','password_reset','nzizaoscar25@gmail.com','ITEC ADMIN CARGO',NULL,NULL,1,'Reset your LMS password','<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Reset your LMS password</title></head><body style=\"margin:0;padding:0;background:#f1f4f7;font-family:Segoe UI,Helvetica,Arial,sans-serif\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%;background:#f1f4f7;padding:24px 12px\"><tr><td align=\"center\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%;max-width:580px;background:#ffffff;border-radius:10px;overflow:hidden;box-shadow:0 2px 10px rgba(20,30,40,.07)\"><tr><td style=\"background:#AD7D00;padding:18px 26px\"><span style=\"color:#ffffff;font-size:16px;font-weight:700;letter-spacing:.4px\">ITEC Cargo ltd</span><span style=\"display:block;color:rgba(255,255,255,.82);font-size:11px;letter-spacing:1.2px;text-transform:uppercase;margin-top:2px\">Logistics Management System</span></td></tr><tr><td style=\"padding:26px\"><h1 style=\"margin:0 0 16px;font-size:19px;line-height:1.35;color:#18222c;font-weight:700\">Reset your password</h1><p style=\"margin:0 0 14px;font-size:15px;line-height:1.6;color:#33404c\">Hello ITEC ADMIN CARGO,</p><p style=\"margin:0 0 14px;font-size:15px;line-height:1.6;color:#33404c\">Someone asked to reset the password on your LMS account. Use the button below to choose a new one.</p><p style=\"margin:0 0 14px;font-size:15px;line-height:1.6;color:#33404c\">The link works once and expires in one hour. If you did not ask for this, ignore this message and your password stays as it is.</p><p style=\"margin:24px 0 8px\"><a href=\"https://lms.superocbs.com/reset-password/ba50443d77eeeda6cb3621f7c6df70f744cfb6c1b137306d40f3a2efd79a6ac7\" style=\"display:inline-block;padding:11px 22px;background:#AD7D00;color:#ffffff;text-decoration:none;border-radius:6px;font-size:14px;font-weight:600\">Choose a new password</a></p><p style=\"margin:0 0 6px;font-size:12px;color:#8a949e\">If the button does not work, open this address:<br><span style=\"color:#5b6670;word-break:break-all\">https://lms.superocbs.com/reset-password/ba50443d77eeeda6cb3621f7c6df70f744cfb6c1b137306d40f3a2efd79a6ac7</span></p></td></tr><tr><td style=\"padding:16px 26px;background:#f7f9fb;border-top:1px solid #e9edf1\"><p style=\"margin:0;font-size:11px;line-height:1.6;color:#8a949e\">This message was sent by the LMS logistics system on behalf of the company named above. Please do not reply to it directly.</p><p style=\"margin:6px 0 0;font-size:11px;color:#9aa4ad\">Powered by ITEC LTD &copy; 2026</p></td></tr></table></td></tr></table></body></html>','Reset your password\n\nHello ITEC ADMIN CARGO,\n\nSomeone asked to reset the password on your LMS account. Use the button below to choose a new one.\n\nThe link works once and expires in one hour. If you did not ask for this, ignore this message and your password stays as it is.\n\n\nChoose a new password: https://lms.superocbs.com/reset-password/ba50443d77eeeda6cb3621f7c6df70f744cfb6c1b137306d40f3a2efd79a6ac7\n\nThis message was sent by the LMS logistics system on behalf of the company named above. Please do not reply to it directly.\nPowered by ITEC LTD (c) 2026',NULL,'users','1','failed',NULL,'Provider: The superocbs.com domain is not verified. Please, add and verify your domain on https://resend.com/domains',1,NULL,'2026-09-26 16:42:38'),(53,'quote-9','notification','imports@kigalihardware.rw','Jean Claude Mugabo',NULL,NULL,NULL,'Quotation for transport, Dar es Salaam to ITEC Kigali Main Warehouse','<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Quotation for transport, Dar es Salaam to ITEC Kigali Main Warehouse</title></head><body style=\"margin:0;padding:0;background:#f1f4f7;font-family:Segoe UI,Helvetica,Arial,sans-serif\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%;background:#f1f4f7;padding:24px 12px\"><tr><td align=\"center\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%;max-width:580px;background:#ffffff;border-radius:10px;overflow:hidden;box-shadow:0 2px 10px rgba(20,30,40,.07)\"><tr><td style=\"background:#AD7D00;padding:18px 26px\"><span style=\"color:#ffffff;font-size:16px;font-weight:700;letter-spacing:.4px\">ITEC Cargo ltd</span><span style=\"display:block;color:rgba(255,255,255,.82);font-size:11px;letter-spacing:1.2px;text-transform:uppercase;margin-top:2px\">Logistics Management System</span></td></tr><tr><td style=\"padding:26px\"><h1 style=\"margin:0 0 16px;font-size:19px;line-height:1.35;color:#18222c;font-weight:700\">Transport quotation — Dar es Salaam to ITEC Kigali Main Warehouse</h1><p style=\"margin:0 0 14px;font-size:15px;line-height:1.6;color:#33404c\">Dear Jean Claude Mugabo,</p><p style=\"margin:0 0 14px;font-size:15px;line-height:1.6;color:#33404c\">Thank you for your enquiry. We are pleased to offer the following terms for carrying your goods from Dar es Salaam to ITEC Kigali Main Warehouse.</p><p style=\"margin:22px 0 8px;font-size:12px;letter-spacing:.8px;text-transform:uppercase;color:#77828d;font-weight:700\">Our offer</p><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%;margin:0 0 18px;border-collapse:collapse\"><tr><th align=\"left\" style=\"padding:8px 10px;background:#f2f5f8;border-bottom:2px solid #AD7D00;font-size:11px;letter-spacing:.6px;text-transform:uppercase;color:#4a5560;font-weight:700\">Detail</th><th align=\"left\" style=\"padding:8px 10px;background:#f2f5f8;border-bottom:2px solid #AD7D00;font-size:11px;letter-spacing:.6px;text-transform:uppercase;color:#4a5560;font-weight:700\">Value</th></tr><tr><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">Goods to be carried</td><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">Building materials: floor tiles, taps, PVC pipes — 1 x 40ft container (MSKU 7788123)</td></tr><tr><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">Weight</td><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">22,000 kg</td></tr><tr><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">Collection from</td><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">Dar es Salaam</td></tr><tr><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">Delivery to</td><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">ITEC Kigali Main Warehouse</td></tr><tr><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">Required by</td><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">7 October 2026</td></tr><tr><td colspan=\"1\" align=\"right\" style=\"padding:9px 10px;font-size:13px;color:#77828d\">Total price</td><td align=\"right\" style=\"padding:9px 10px;font-size:15px;color:#18222c;font-weight:700;border-top:1px solid #e9edf1\">USD 3,200.00</td></tr></table><p style=\"margin:0 0 12px;font-size:14px;line-height:1.6;color:#5b6670\">The price above is for the weight shown and includes carriage from Dar es Salaam to ITEC Kigali Main Warehouse. A heavier load is quoted again, since it takes more of the vehicle.</p><p style=\"margin:0 0 12px;font-size:14px;line-height:1.6;color:#5b6670\">This quotation is open for acceptance until 31 October 2026.</p><p style=\"margin:0 0 12px;font-size:14px;line-height:1.6;color:#5b6670\">To accept, simply reply to this message. Please quote reference REQ-2026-0003 in any correspondence.</p></td></tr><tr><td style=\"padding:16px 26px;background:#f7f9fb;border-top:1px solid #e9edf1\"><p style=\"margin:0;font-size:11px;line-height:1.6;color:#8a949e\">Sent by ITEC Cargo ltd. You may reply to this message and it will reach us.</p><p style=\"margin:6px 0 0;font-size:11px;color:#9aa4ad\">Powered by ITEC LTD &copy; 2026</p></td></tr></table></td></tr></table></body></html>','Transport quotation — Dar es Salaam to ITEC Kigali Main Warehouse\n\nDear Jean Claude Mugabo,\n\nThank you for your enquiry. We are pleased to offer the following terms for carrying your goods from Dar es Salaam to ITEC Kigali Main Warehouse.\n\nOUR OFFER\n  Detail: Goods to be carried  |  Value: Building materials: floor tiles, taps, PVC pipes — 1 x 40ft container (MSKU 7788123)\n  Detail: Weight  |  Value: 22,000 kg\n  Detail: Collection from  |  Value: Dar es Salaam\n  Detail: Delivery to  |  Value: ITEC Kigali Main Warehouse\n  Detail: Required by  |  Value: 7 October 2026\n  Total price: USD 3,200.00\n\n\nThe price above is for the weight shown and includes carriage from Dar es Salaam to ITEC Kigali Main Warehouse. A heavier load is quoted again, since it takes more of the vehicle.\n\nThis quotation is open for acceptance until 31 October 2026.\n\nTo accept, simply reply to this message. Please quote reference REQ-2026-0003 in any correspondence.\n\nSent by ITEC Cargo ltd. You may reply to this message and it will reach us.\nPowered by ITEC LTD (c) 2026',NULL,'requests','REQ-2026-0003','skipped',NULL,'Not sent from the console; the message is queued.',1,NULL,'2026-10-01 14:52:10'),(54,'n-6abe739af09342.21566408-u2','notification','aline@itec.rw','Aline Mukamana',NULL,NULL,2,'Transport request approved','<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Transport request approved</title></head><body style